import{_ as s,C as n,o as d,c as l,al as a,j as t,a as i,E as r}from"./chunks/framework.7vp1BMOE.js";const v=JSON.parse('{"title":"Descend Mode (Fixed-Wing)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_modes_fw/descend.md","filePath":"uk/flight_modes_fw/descend.md"}'),h={name:"uk/flight_modes_fw/descend.md"},c={class:"tip custom-block"};function m(f,e,u,_,p,g){const o=n("Badge");return d(),l("div",null,[e[8]||(e[8]=a('<h1 id="descend-mode-fixed-wing" tabindex="-1">Descend Mode (Fixed-Wing) <a class="header-anchor" href="#descend-mode-fixed-wing" aria-label="Permalink to &quot;Descend Mode (Fixed-Wing)&quot;">​</a></h1><p><em>Descend</em> is a <a href="./../config/safety">failsafe</a> fallback mode that is activated automatically by PX4. The mode is published when active but cannot be selected by the pilot.</p><p>The vehicle descends open-loop: it circles at a fixed bank angle (<a href="./../advanced_config/parameter_reference#FW_GPSF_R">FW_GPSF_R</a>) and descends at a fixed 0.5 m/s, but does not control its ground position, so the circle drifts with the wind. It is the last resort used when the vehicle must come down but has no valid position estimate for a controlled descent.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li>Mode is automatic and cannot be selected by the user.</li><li>Requires only attitude, so it works without a position estimate.</li><li>The vehicle first loiters at the current altitude for <a href="./../advanced_config/parameter_reference#FW_GPSF_LT">FW_GPSF_LT</a> seconds (waiting for the estimate to recover) before starting to descend.</li></ul></div><h2 id="технічнии-опис" tabindex="-1">Технічний опис <a class="header-anchor" href="#технічнии-опис" aria-label="Permalink to &quot;Технічний опис&quot;">​</a></h2><h3 id="when-it-occurs" tabindex="-1">When It Occurs <a class="header-anchor" href="#when-it-occurs" aria-label="Permalink to &quot;When It Occurs&quot;">​</a></h3><p>Descend mode is at the bottom of the failsafe chain (along with <a href="./../advanced_config/flight_termination">Flight termination</a>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hold → Return → Land → ( Descend | Terminate )</span></span></code></pre></div>',8)),t("div",c,[e[7]||(e[7]=t("p",{class:"custom-block-title"},"TIP",-1)),t("p",null,[e[0]||(e[0]=t("a",{href:"./../advanced_config/parameter_reference#COM_POS_FS_ACT"},"COM_POS_FS_ACT",-1)),e[1]||(e[1]=i()),r(o,{type:"tip",text:"main (PX4 v2.0)"}),e[2]||(e[2]=i(" selects whether ",-1)),e[3]||(e[3]=t("code",null,"Descend",-1)),e[4]||(e[4]=i(" or ",-1)),e[5]||(e[5]=t("code",null,"Terminate",-1)),e[6]||(e[6]=i(" is used as the failsafe.",-1))])]),e[9]||(e[9]=a('<p>PX4 falls through to Descend mode whenever a failsafe needs to bring the vehicle down or hold position but the position estimate is missing, so none of the higher options can run. Наприклад:</p><ul><li>Losing the position estimate while landing, e.g. GNSS and airspeed sensors fail during <a href="./../flight_modes_fw/land">Land</a>: the vehicle keeps descending, but now open-loop as <em>Descend</em>.</li><li>Losing the position estimate in <a href="./../flight_modes_fw/hold">Hold</a>, <a href="./../flight_modes_fw/mission">Mission</a> or <a href="./../flight_modes_fw/return">Return</a>: with no position to hold, fly to, or return with, the failsafe escalates down to <em>Descend</em>.</li><li>A Return or Land failsafe (from manual control loss, GCS/data link loss, low battery, geofence breach, …) triggered while no valid position estimate is available: Return and Land can&#39;t run, so it degrades to <em>Descend</em>.</li></ul><h3 id="exiting-descend" tabindex="-1">Exiting Descend <a class="header-anchor" href="#exiting-descend" aria-label="Permalink to &quot;Exiting Descend&quot;">​</a></h3><p>Descend ends when either the:</p><ul><li>failsafe condition is resolved (e.g. the position estimate recovers), and the vehicle returns to its previous mode; or</li><li>pilot takes over by switching to a manual mode (<a href="./../flight_modes_fw/cruise">Cruise</a>, <a href="./../flight_modes_fw/altitude">Altitude</a> or <a href="./../flight_modes_fw/stabilized">Stabilized</a>).</li></ul><h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_prevent_arming"><code>mode_req_prevent_arming</code></a> — Mode prevents arming</li></ul><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="./../flight_modes_mc/descend">Descend Mode (MC)</a></li><li><a href="./../flight_modes_fw/land">Режим посадки (FW)</a></li><li><a href="./../config/safety">Safety (Failsafes)</a></li></ul>',10))])}const w=s(h,[["render",m]]);export{v as __pageData,w as default};
